/* eslint-disable prefer-destructuring */

function saveEval(jsCode, context = {}) {
  // TODO eval
  const addcontext = Object.keys(context).map((key) => `let ${key}=context["${key}"];`).join('');
  // eslint-disable-next-line no-eval
  return eval(addcontext + jsCode);
}

